{"id": "uk415", "theme": "basics", "rule": "General rules", "question": "What does the law say about driving without due care and attention?", "options": ["It is not an offence if no one is hurt", "It only applies to drivers of lorries", "It is only a warning with no penalty", "It is an offence, and can lead to a fine and penalty points"], "correctIndex": 3, "explanation": "Careless driving is an offence. You can be fined, get penalty points and be disqualified."},
{"id": "uk416", "theme": "basics", "rule": "General rules", "question": "What should you do if you are being followed closely by another vehicle?", "options": ["Brake sharply to make them back off", "Speed up to get away from them", "Keep a steady speed and do not brake suddenly", "Wave them past with your hand"], "correctIndex": 2, "explanation": "Slow down gradually to increase your gap to the vehicle in front, which also gives you more time to stop."},
{"id": "uk417", "theme": "basics", "rule": "Rule 126", "question": "What is the correct gap to keep from the vehicle in front in good conditions?", "options": ["At least a two-second gap", "A gap of half a second", "A gap of one second only", "A gap of five seconds or more"], "correctIndex": 0, "explanation": "Use the two-second rule on roads with good surface and dry weather. Double it when wet."},
{"id": "uk418", "theme": "basics", "rule": "General rules", "question": "What should you do if your brakes feel 'spongy'?", "options": ["Stop safely and have them checked", "Carry on driving as normal", "Pump them as you drive along", "Use only the handbrake to stop"], "correctIndex": 0, "explanation": "Spongy brakes can be a sign of a serious problem. Do not carry on driving."},
{"id": "uk419", "theme": "basics", "rule": "General rules", "question": "When may you use the horn?", "options": ["To say hello to other road users", "To show your frustration to others", "To warn others of your presence", "To ask a pedestrian to move on"], "correctIndex": 2, "explanation": "Only use the horn while moving. Do not use it in a built-up area between 11.30 pm and 7 am."},
{"id": "uk420", "theme": "basics", "rule": "General rules", "question": "What can you do to drive in a way that uses less fuel?", "options": ["Use high revs in each gear", "Brake late for each hazard", "Keep the engine running when stopped", "Accelerate smoothly and anticipate the road"], "correctIndex": 3, "explanation": "Smooth acceleration, early braking, and keeping the right tyre pressure all help to save fuel."},
{"id": "uk421", "theme": "basics", "rule": "General rules", "question": "What does flashing your headlights mean?", "options": ["It is only to let others know you are there", "That you are giving way to another driver", "That you are asking others to give way", "That there is an emergency on the road"], "correctIndex": 0, "explanation": "Only flash your headlights to let others know you are there. Never use it to signal that you are giving way."},
{"id": "uk422", "theme": "basics", "rule": "General rules", "question": "What is the meaning of a signal from a police officer to stop with the arm raised?", "options": ["You may slow down and go on", "You may go ahead if the road is clear", "You must turn left at once", "You must stop"], "correctIndex": 3, "explanation": "When an officer in uniform shows their palm to traffic or signals you to stop, you must stop."},
{"id": "uk423", "theme": "basics", "rule": "General rules", "question": "What should you do when a school crossing patrol shows a 'Stop for children' sign?", "options": ["Slow down and drive on past it", "Stop and wait until the road is clear", "Pass if you can see no children", "Sound your horn to warn the children"], "correctIndex": 1, "explanation": "You must stop when the patrol steps into the road with the sign. Wait until they and the children have crossed."},
{"id": "uk424", "theme": "basics", "rule": "General rules", "question": "What does a 'No stopping' sign (red cross on a blue disc) mean?", "options": ["You may stop there for two minutes", "You may stop there at night only", "You may stop there to load goods", "You must not stop at any time"], "correctIndex": 3, "explanation": "A red cross on a blue disc means no stopping at any time (a clearway)."}
